#ifndef ASCIR_DIALECT_UTILS_REGISTRATION_H
#define ASCIR_DIALECT_UTILS_REGISTRATION_H

#include "ascir/Dialect/Asc/IR/Asc.h"
#include "ascir/Dialect/Asc/Transforms/Passes.h"
